{
     "title": "CSCI-250: Concepts of Computer Systems - Lesson Blueprint",
     "learningObjectives": [
       "Define the multilevel model of computer organization and explain how each level interfaces with the levels above and below it.",
       "Explain the role of system calls, traps, and user/kernel mode transitions in managing privileged operations and resource access.",
       "Apply the concepts of virtual memory, scheduling, and concurrency to analyze how operating systems manage multiple processes efficiently."
     ],
     "beats": [
       {
         "title": "Introduction to Multilevel Architecture",
         "claim": "Computer systems are organized into a multilevel model that spans from digital logic to high-level operating systems.",
         "example": "This hierarchy allows developers to write assembly code that directly manipulates registers while the OS handles memory and scheduling.",
         "visualDirection": "Display a stacked diagram showing five layers: digital logic, microarchitecture, instruction set, OS, and assembly, with arrows indicating upward abstraction and downward control.",
         "sourceIds": ["rit-csci-250"]
       },
       {
         "title": "Digital Logic and Microarchitecture Basics",
         "claim": "The digital logic level implements basic gates and circuits that form the foundation for all subsequent hardware components.",
         "example": "A simple AND gate combines two input signals to produce a single output, enabling complex logic in modern processors.",
         "visualDirection": "Show a schematic of basic logic gates (AND, OR, NOT) connected to form a simple adder, highlighting signal flow.",
         "sourceIds": ["rit-csci-250"]
       },
       {
         "title": "Microarchitecture and Instruction Set Interface",
         "claim": "Microarchitecture translates high-level instructions into precise hardware operations that execute on the processor.",
         "example": "A branch instruction alters the control flow by updating the program counter based on a condition evaluated by the CPU.",
         "visualDirection": "Illustrate a pipeline diagram showing how an instruction moves through fetch, decode, execute, and write-back stages.",
         "sourceIds": ["rit-csci-250", "riscv-unprivileged"]
       },
       {
         "title": "Machine Instruction Set Level",
         "claim": "The machine instruction set defines the precise commands that programmers can issue to control hardware behavior.",
         "example": "A load instruction transfers data from a memory address into a specific register for subsequent computation.",
         "visualDirection": "Display a table mapping common RISC-V instructions to their register and memory operands, emphasizing data flow.",
         "sourceIds": ["riscv-unprivileged"]
       },
       {
         "title": "Operating System Level Overview",
         "claim": "The operating system manages hardware resources and provides an interface for multiple programs to run concurrently.",
         "example": "The OS allocates CPU time to different processes using a scheduler that prioritizes runnable tasks.",
         "visualDirection": "Draw a flowchart showing process creation, scheduling decision, context switch, and resource allocation steps.",
         "sourceIds": ["rit-csci-250"]
       },
       {
         "title": "User Mode and Kernel Mode Transitions",
         "claim": "Processes execute in user mode for normal tasks, while privileged operations require a transition to kernel mode.",
         "example": "A system call transfers control from user code to a privileged kernel service to access hardware or manage memory.",
         "visualDirection": "Show a side-by-side comparison of user mode (restricted permissions) and kernel mode (full hardware access) with a transition arrow.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "System Calls and Traps Mechanism",
         "claim": "System calls use traps to safely transfer control to the kernel while preserving processor state for later return.",
         "example": "When a process requests file I/O, a trap records the CPU registers so the kernel can handle the request and restore state.",
         "visualDirection": "Create a sequence diagram showing the trap entry, kernel handling, and return path with state preservation markers.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Virtual Memory and Page Tables",
         "claim": "Page tables map virtual addresses to physical memory locations, enabling efficient memory management and protection.",
         "example": "A page table entry contains a physical address pointer and permission bits that determine access rights for each memory block.",
         "visualDirection": "Illustrate a two-level page table structure with arrows linking virtual addresses to physical frames, highlighting permission bits.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Concurrency, Locks, and Scheduling",
         "claim": "Locks protect shared resources from concurrent access, while the scheduler ensures fair CPU distribution among processes.",
         "example": "A mutex lock prevents two processes from modifying a shared counter simultaneously, maintaining data integrity.",
         "visualDirection": "Display a diagram of a shared resource with a lock mechanism, showing how processes queue and acquire exclusive access.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Students can verify system behavior by checking data dependencies, control flow, and resource ownership across all levels.",
         "example": "An analyst reviews a process trace to confirm that traps preserved state, locks protected invariants, and page tables mapped correctly.",
         "visualDirection": "Provide a checklist template with boxes for verifying: state preservation, lock invariants, page table mappings, and scheduling fairness.",
         "sourceIds": ["mit-xv6-book", "rit-csci-250"]
       }
     ]
   }
